package com.astrocare.security;
import com.astrocare.entity.User; import com.astrocare.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class DatabaseUserDetailsService implements UserDetailsService { private final UserRepository repo; public UserDetails loadUserByUsername(String username)throws UsernameNotFoundException{User u=repo.findByUsername(username).orElseThrow(()->new UsernameNotFoundException("Invalid credentials"));return new org.springframework.security.core.userdetails.User(u.getUsername(),u.getPasswordHash(),u.isEnabled(),true,true,true,u.getRoles().stream().map(r->new SimpleGrantedAuthority(r.getName().name())).toList());} }
